import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import { createHash, randomUUID } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { Database } from 'bun:sqlite';

const base = path.resolve(process.argv[2]);
const config = JSON.parse(fs.readFileSync(path.join(base, 'config.json'), 'utf8'));
const spec = JSON.parse(fs.readFileSync(process.argv[3], 'utf8'));
const slotDir = path.dirname(process.argv[3]);
assert.ok(slotDir.startsWith(path.join(base, 'results') + '/'));
const policy = JSON.parse(fs.readFileSync(path.join(base, 'policy.json'), 'utf8'));
const httpEvents=[];
const originalFetch=globalThis.fetch;
globalThis.fetch=async (input,init)=>{
  const url=typeof input==='string'?input:input instanceof URL?input.href:input.url;
  if(url!=='https://askgina.ai/ai/gina/mcp') return originalFetch(input,init);
  const start=Date.now();
  let rpcMethod=null;
  try {const m=JSON.parse(init?.body)?.method;if(['initialize','tools/list','tools/call','notifications/initialized'].includes(m))rpcMethod=m;}catch{}
  try {
    const response=await originalFetch(input,init);
    if(httpEvents.length<1000)httpEvents.push({at:new Date(start).toISOString(),rpcMethod,status:response.status,durationMs:Date.now()-start});
    return response;
  } catch(error){
    if(httpEvents.length<1000)httpEvents.push({at:new Date(start).toISOString(),rpcMethod,durationMs:Date.now()-start,errorType:error?.name??'Error',code:/^[A-Z0-9_]{1,32}$/.test(error?.code)?error.code:null,causeCode:/^[A-Z0-9_]{1,32}$/.test(error?.cause?.code)?error.cause.code:null});
    throw error;
  }
};
const root = config.sourceRoot;
const resolve = name => Bun.resolveSync(name, root + '/packages/evals');
const { Effect, Exit, Layer, Redacted, Schema } = await import(resolve('effect'));
const BunServices = await import(resolve('@effect/platform-bun/BunServices'));
const BunHttpClient = await import(resolve('@effect/platform-bun/BunHttpClient'));
const { listCatalogToolNames, catalogSha } = await import(resolve('@askgina/contracts'));
const evals = await import(root + '/packages/evals/dist/index.js');
const { preflightLiveEvalSuite } = await import(root + '/packages/evals/src/live.ts');
const hash = bytes => createHash('sha256').update(bytes).digest('hex');
const stamp = () => new Date().toISOString();
assert.equal(hash(fs.readFileSync(new URL(import.meta.url))), policy.workerSha256, 'worker hash mismatch');
for (const [file, digest] of Object.entries(config.hashes)) {
  assert.equal(hash(fs.readFileSync(file)), digest, `hash mismatch: ${file}`);
}
assert.equal(execFileSync(config.executablePath, ['--version'], { encoding: 'utf8' }).trim(), `omp/${config.methodology.ompVersion}`);
